import { describe, test, expect } from "vitest";
import { defu } from "../src/defu.ts";

describe("prototype pollution via __proto__", () => {
  test("does not pollute Object.prototype via __proto__ in defaults", () => {
    const before = ({} as any).polluted;
    expect(before).toBe(undefined);

    const malicious = JSON.parse('{"__proto__":{"polluted":true}}');
    defu({}, malicious);

    const after = ({} as any).polluted;
    expect(after).toBe(undefined);
  });

  test("does not pollute Object.prototype via __proto__ in baseObject", () => {
    const malicious = JSON.parse('{"__proto__":{"polluted":true}}');
    defu(malicious, {});

    const after = ({} as any).polluted;
    expect(after).toBe(undefined);
  });

  test("does not pollute Object.prototype via __proto__ in both args", () => {
    const malicious1 = JSON.parse('{"__proto__":{"polluted1":true}}');
    const malicious2 = JSON.parse('{"__proto__":{"polluted2":true}}');
    defu(malicious1, malicious2);

    expect(({} as any).polluted1).toBe(undefined);
    expect(({} as any).polluted2).toBe(undefined);
  });

  test("treats __proto__ as a regular key in the result", () => {
    const malicious = JSON.parse('{"__proto__":{"polluted":true},"key":"value"}');
    const result = defu({}, malicious) as any;

    // __proto__ should not cause prototype pollution
    expect(({} as any).polluted).toBe(undefined);

    // The key property should still be present
    expect(result.key).toBe("value");
  });

  test("does not corrupt the result object's prototype chain", () => {
    const malicious = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu({}, malicious) as any;

    // Result should still be a plain object
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty).toBeDefined(); // should inherit from Object.prototype
  });

  test("constructor in defaults does not pollute", () => {
    const malicious = JSON.parse('{"constructor":{"prototype":{"isAdmin":true}}}');
    defu({}, malicious);
    // @ts-ignore
    expect(({} as any).isAdmin).toBe(undefined);
  });
});
EOF
